package br.com.onda.torrentprobe;
import bt.Bt;
import bt.runtime.*;
import bt.metainfo.*;
import bt.data.file.FileSystemStorage;
import bt.dht.*;
import bt.torrent.fileselector.FilePriority;
import org.junit.Test;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
import java.io.*;
import java.net.*;
import java.nio.*;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.regex.*;

/** Isolated loopback-only compatibility proof. No public swarm, no user files. */
public class TorrentProbeTest {
 static byte[] encode(Object o)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();write(out,o);return out.toByteArray();}
 static void write(OutputStream out,Object o)throws Exception{if(o instanceof byte[]){byte[] b=(byte[])o;out.write((b.length+":").getBytes("UTF-8"));out.write(b);}else if(o instanceof String)write(out,((String)o).getBytes("UTF-8"));else if(o instanceof Number)out.write(("i"+o+"e").getBytes("UTF-8"));else if(o instanceof Map){out.write('d');for(Object key:new TreeSet<>(((Map<String,Object>)o).keySet())){write(out,key);write(out,((Map<?,?>)o).get(key));}out.write('e');}else throw new IOException("Unsupported object");}
 static int port()throws Exception{try(ServerSocket s=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){return s.getLocalPort();}}
 static Config config()throws Exception{Config c=new Config();c.setAcceptorAddress(InetAddress.getByName("127.0.0.1"));c.setAcceptorPort(port());c.setMseDisabled(true);c.setNumOfHashingThreads(1);c.setMaxPeerConnections(3);c.setMaxPeerConnectionsPerTorrent(2);c.setMaxConcurrentlyActivePeerConnectionsPerTorrent(1);c.setPeerDiscoveryInterval(Duration.ofSeconds(1));c.setTrackerQueryInterval(Duration.ofSeconds(1));c.setTrackerTimeout(Duration.ofSeconds(3));c.setMaxMessageProcessingInterval(Duration.ofMillis(200));c.setMetadataExchangeMaxSize(1024*1024);return c;}
 static class Swarm implements AutoCloseable {
  final byte[] payload=new byte[24576],info,hash;final ServerSocket tcp;final DatagramSocket udp;final ExecutorService workers=Executors.newCachedThreadPool();final AtomicInteger blocks=new AtomicInteger();volatile boolean closed;final List<Socket> sockets=new CopyOnWriteArrayList<>();
  Swarm()throws Exception{new Random(123).nextBytes(payload);ByteArrayOutputStream hashes=new ByteArrayOutputStream();for(int at=0;at<payload.length;at+=16384)hashes.write(MessageDigest.getInstance("SHA-1").digest(Arrays.copyOfRange(payload,at,Math.min(at+16384,payload.length))));Map<String,Object> map=new TreeMap<>();map.put("name","probe.mp4");map.put("length",payload.length);map.put("piece length",16384);map.put("pieces",hashes.toByteArray());info=encode(map);hash=MessageDigest.getInstance("SHA-1").digest(info);tcp=new ServerSocket(0,4,InetAddress.getByName("127.0.0.1"));udp=new DatagramSocket(new InetSocketAddress("127.0.0.1",0));workers.execute(this::tracker);workers.execute(()->{while(!closed)try{Socket s=tcp.accept();sockets.add(s);s.setSoTimeout(30000);workers.execute(()->serve(s));}catch(Exception e){if(!closed)e.printStackTrace();}});}
  String trackerUrl(){return "udp://127.0.0.1:"+udp.getLocalPort()+"/announce";}
  void tracker(){while(!closed)try{byte[] b=new byte[2048];DatagramPacket p=new DatagramPacket(b,b.length);udp.receive(p);ByteBuffer req=ByteBuffer.wrap(b,0,p.getLength()).order(ByteOrder.BIG_ENDIAN);int action=req.getInt(8),transaction=req.getInt(12);ByteBuffer out;if(action==0)out=ByteBuffer.allocate(16).putInt(0).putInt(transaction).putLong(12345678);else if(action==1)out=ByteBuffer.allocate(26).putInt(1).putInt(transaction).putInt(1).putInt(1).putInt(1).put(new byte[]{127,0,0,1}).putShort((short)tcp.getLocalPort());else continue;udp.send(new DatagramPacket(out.array(),out.position(),p.getSocketAddress()));}catch(Exception e){if(!closed)e.printStackTrace();}}
  void send(DataOutputStream out,int id,byte[] body)throws Exception{out.writeInt(body.length+1);out.writeByte(id);out.write(body);out.flush();}
  void extended(DataOutputStream out,int ext,byte[] body)throws Exception{byte[] data=new byte[body.length+1];data[0]=(byte)ext;System.arraycopy(body,0,data,1,body.length);send(out,20,data);}
  void serve(Socket socket){try(Socket s=socket){DataInputStream in=new DataInputStream(s.getInputStream());DataOutputStream out=new DataOutputStream(s.getOutputStream());byte[] handshake=new byte[68];in.readFully(handshake);assertEquals(19,handshake[0]);byte[] reserved=new byte[8];reserved[5]=16;out.writeByte(19);out.write("BitTorrent protocol".getBytes("US-ASCII"));out.write(reserved);out.write(hash);out.write("-OT0001-123456789012".getBytes("US-ASCII"));out.flush();send(out,5,new byte[]{(byte)0xc0});send(out,1,new byte[0]);Map<String,Object> extension=new TreeMap<>();extension.put("m",Collections.singletonMap("ut_metadata",1));extension.put("metadata_size",info.length);extended(out,0,encode(extension));int clientMeta=1;while(!closed){int n=in.readInt();if(n==0)continue;if(n<1||n>1024*1024)throw new IOException("Message bound");byte[] message=new byte[n];in.readFully(message);int id=message[0]&255;if(id==20&&n>2){if(message[1]==0){Matcher m=Pattern.compile("11:ut_metadatai([0-9]+)e").matcher(new String(message,2,n-2,"UTF-8"));if(m.find())clientMeta=Integer.parseInt(m.group(1));}else{Map<String,Object> response=new TreeMap<>();response.put("msg_type",1);response.put("piece",0);response.put("total_size",info.length);ByteArrayOutputStream body=new ByteArrayOutputStream();body.write(encode(response));body.write(info);extended(out,clientMeta,body.toByteArray());}}else if(id==6&&n==13){ByteBuffer request=ByteBuffer.wrap(message,1,12);int index=request.getInt(),begin=request.getInt(),length=request.getInt(),start=index*16384+begin;if(start<0||length<1||length>16384||start+length>payload.length)throw new IOException("Invalid block");blocks.incrementAndGet();ByteBuffer reply=ByteBuffer.allocate(8+length).putInt(index).putInt(begin).put(payload,start,length);send(out,7,reply.array());}}}catch(Exception e){if(!closed&&!(e instanceof EOFException)&&!(e instanceof SocketException))e.printStackTrace();}}
  public void close(){closed=true;try{tcp.close();udp.close();for(Socket s:sockets)s.close();}catch(Exception ignored){}workers.shutdownNow();}
 }
 static byte[] torrent(Swarm s)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write("d8:announce".getBytes("UTF-8"));write(out,s.trackerUrl());out.write("4:info".getBytes("UTF-8"));out.write(s.info);out.write('e');return out.toByteArray();}
 @Test public void androidCanDownloadVerifiedPiecesAndResolveMagnetMetadata()throws Exception{try(Swarm swarm=new Swarm()){File root=new File(getInstrumentation().getTargetContext().getCacheDir(),"bt-probe-"+UUID.randomUUID());assertTrue(root.mkdirs());Torrent t=new MetadataService().fromByteArray(torrent(swarm));assertEquals(swarm.payload.length,t.getSize());BtRuntime runtime=BtRuntime.builder(config()).disableLocalServiceDiscovery().disablePeerExchange().build();BtClient client=Bt.client(runtime).storage(new FileSystemStorage(root)).torrent(()->t).stopWhenDownloaded().build();try{client.startAsync().get(35,TimeUnit.SECONDS);assertArrayEquals(swarm.payload,Files.readAllBytes(new File(root,"probe.mp4").toPath()));assertTrue(swarm.blocks.get()>0);}finally{client.stop();runtime.shutdown();new File(root,"probe.mp4").delete();root.delete();}
   StringBuilder hex=new StringBuilder();for(byte b:swarm.hash)hex.append(String.format(Locale.ROOT,"%02x",b&255));String magnet="magnet:?xt=urn:btih:"+hex+"&tr="+URLEncoder.encode(swarm.trackerUrl(),"UTF-8");AtomicReference<Torrent> metadata=new AtomicReference<>();int before=swarm.blocks.get();File metaRoot=new File(getInstrumentation().getTargetContext().getCacheDir(),"bt-meta-"+UUID.randomUUID());metaRoot.mkdirs();BtRuntime second=BtRuntime.builder(config()).disableLocalServiceDiscovery().disablePeerExchange().build();BtClient resolver=Bt.client(second).storage(new FileSystemStorage(metaRoot)).magnet(magnet).afterTorrentFetched(metadata::set).fileSelector(file->FilePriority.SKIP).stopWhenDownloaded().build();try{resolver.startAsync().get(35,TimeUnit.SECONDS);assertNotNull(metadata.get());assertEquals(t.getTorrentId(),metadata.get().getTorrentId());assertEquals(before,swarm.blocks.get());}finally{resolver.stop();second.shutdown();for(File f:Objects.requireNonNull(metaRoot.listFiles()))f.delete();metaRoot.delete();}
  }}
 @Test public void dhtCanStartAndStopWithoutPublicBootstrap()throws Exception{DHTConfig d=new DHTConfig();d.setListeningPort(port());d.setShouldUseRouterBootstrap(false);BtRuntime runtime=BtRuntime.builder(config()).disableLocalServiceDiscovery().disablePeerExchange().module(new DHTModule(d)).build();try{runtime.startup();assertTrue(runtime.isRunning());}finally{runtime.shutdown();}assertFalse(runtime.isRunning());}
}
